 refresh:'<path d="M20 10a8 8 0 0 0-14-5L3 8M3 3v5h5M4 14a8 8 0 0 0 14 5l3-3M16 16h5v5"/>',
 lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 15v3"/>',
 map:'<path d="m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3zM9 2v17M15 5v17"/>',
